#!/bin/bash
# Copyright © 2026 Jack Lusher. All rights reserved.
# Usage: scripts/escapement/pools.sh <out dir> <seeds> <layout> <clocks> <moves>... [-- waits a-b]
# Deals Escapement problems backwards from a line with the prover's build mode, for each count of moves given, over
# seeds 1 to <seeds>, and keeps those with one line in whole heals and waits as book rows (seed as the number) in
# <out dir>/<layout>-<clocks>-<moves>.tsv, and no seam of six steps or more, measured beside it in .measure.tsv, so a
# pool is regenerated by its command.
# ESC_INSIDE (the share of heals inside a clock's edge) and ESC_WAITS (default 0-2) pass through.
set -euo pipefail
cd "$(dirname "$0")/../.."
out=$1 seeds=$2 layout=$3 clocks=$4
shift 4
mkdir -p "$out"
scripts/escapement.sh >/dev/null 2>&1 || true
for n in "$@"; do
  name="$out/$layout-${clocks//,/_}-$n${ESC_INSIDE:+-in$ESC_INSIDE}"
  build/escapement/prove build "$layout" "$clocks" "$n" "${ESC_WAITS:-0-2}" 1 "$seeds" |
    awk -F'\t' -v l="$layout" -v c="$clocks" '$9 == 1 {
      # A seam of 6 steps or more reads as a turn the other way, or none, so the book deals none.
      k = split($12, e, ","); ok = 1
      for (i = 1; i <= k; i++) { split(e[i], f, ":"); s = f[2] + 0; if (s >= 6 || s <= -6) ok = 0 }
      if (ok) print $5 "\t" l "\t" c "\t" $12 }' > "$name.tsv"
  build/escapement/prove measure "$name.tsv" > "$name.measure.tsv"
  echo "$name: $(($(wc -l < "$name.measure.tsv") - 1)) with one line"
done
